#define TRICK_NUM 95

template<class T>
class list
{
    void *node;
public:
    void resize(unsigned int, const T &);
    void push_back(const T &);
};

class ScoringManager
{
public:
    enum SPECIALTRICK
    {
        SPECIALTRICK_NONE,
        SPECIALTRICK_SUCCEEDED,
        SPECIALTRICK_FAILED
    };

    struct LevelTrick
    {
        int numLandings;
    };

    class Series
    {
        friend class ScoringManager;
        LevelTrick *levelTricks;
    public:
        void *tricks;
        int numSpins;
        int landing;
        int flags;

        Series();
        ~Series() { }
    };

    class Chain
    {
        LevelTrick *levelTricks;
        float multAdder;
    public:
        list<Series> series;
    };

private:
    void *vtable;
    int score;
    void *ksctrl;
    int playerIdx;
    void *specialMeter;
    LevelTrick levelTricks[95];
    Chain bestChain;
    int bestChainScore;
    float longestTubeRide;
    float longestFloater;
    float longestAir;
    Chain chain;
    int facePoints;
    int airPoints;
    int tubePoints;
    int num360spins;
    int num540spins;
    int prevTrickRegion;
    float lipDist;
    float mouthDist;
    int specialTrick;

public:
    void Reset(void);
};

